INSERT INTO "task_definition" ("task_id","schema_version","title","objective","source_path","status_detail","explicit_activation_required","intake_path","archive_path","archive_sha256") VALUES ('bulk-silicon.records.periodic.extraction',3,'Periodic electronic-structure record extraction','Determine and implement the minimal plane-wave Kohn-Sham calculation record supported by the observed QE tutorial QEXSD artifact, with QEXSD I/O, periodic geometry, representation-neutral Kohn-Sham semantics, and plane-wave ownership separated.','harness/tasks/bulk-silicon.records.periodic.extraction.json','Human-accepted PASS for the limited claim that the observed QE 7.2 QEXSD artifact was faithfully transformed through separated Quantum ESPRESSO I/O, periodic-geometry, Kohn–Sham, and plane-wave-record domains with explicit units, coordinate conventions, reciprocal scaling, provenance, and unavailable metadata. Acceptance does not establish numerical convergence beyond the retained tutorial observation, physical validation, transferability to other QE calculations, completeness of the plane-wave basis description, suitability for Wannier or effective-mass analysis, or scientific acceptance of downstream results. Automatic successor activation remains disabled; no successor is active.',1,NULL,NULL,NULL);
INSERT INTO "task_definition" ("task_id","schema_version","title","objective","source_path","status_detail","explicit_activation_required","intake_path","archive_path","archive_sha256") VALUES ('bulk-silicon.semiconductor-properties',3,'Bulk-silicon semiconductor-property program','Coordinate band-edge-level semiconductor properties, carrier statistics, conditional screening and deformation-potential branches, visualizations, numerical verification, and bounded physical validation for later EMT use.','harness/tasks/bulk-silicon.semiconductor-properties.json','Planning-only property and acceptance boundary. Immediate deterministic properties branch from accepted band-edge/DOS data; dielectric and strain properties are conditional.',1,NULL,NULL,NULL);
