INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.architecture-v2.simulation-execution','authorized_scope',0,'Slice 1, simulation and package architecture: establish calculator-independent simulation contracts, calculator-specific Quantum ESPRESSO simulation specifications and executors, artifact identities, scientific-analysis boundaries, Workflow, WorkflowRun, and execution-result ownership without creating a second workflow graph beside the maintained CPN contract; workflows references colored-Petri-net contracts owned by petrinet.colored.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.architecture-v2.simulation-execution','authorized_scope',1,'Slice 2, direct accepted QE tutorial baselines: represent the accepted silicon Davidson SCF and bands tutorials with exact retained inputs and identities, and verify direct execution behavior only through deterministic replay or fake-process evidence without invoking a scientific executable.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.architecture-v2.simulation-execution','authorized_scope',2,'Slice 3, calculator-independent CPN solutions: represent the same tutorial simulations as CPN-backed Workflows, reuse the same simulation definitions and executor contract, and verify ordering, authorization, dependency, terminal-state, failure, and direct-versus-CPN replay equivalence behavior.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.architecture-v2.simulation-execution','authorized_scope',3,'Keep the development HarnessTask lifecycle, scientific Workflow and WorkflowRun state, calculator execution observations, deterministic scientific analysis, and human-reviewed external research conclusions separate; do not introduce ScientificDisposition workflow state.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.architecture-v2.simulation-execution','authorized_scope',4,'Use typed model features with derived tags where calculator capability classification is required; do not encode scientific parameters in Workflow records.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.architecture-v2.simulation-execution','authorized_scope',5,'Preserve optional future adapter compatibility without adding integration dependencies on AiiDA, Airflow, or pymatgen.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.architecture-v2.simulation-execution','completion_criterion',0,'The direct tutorial execution model represents the accepted QE SCF and bands tutorial definitions and their immutable unexecuted-to-completed lifecycle under deterministic replay.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.architecture-v2.simulation-execution','completion_criterion',1,'Calculator-independent CPN-backed Workflows represent the same tutorials using maintained CPN enablement and firing semantics rather than another dependency graph or shell-loop workflow authority.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.architecture-v2.simulation-execution','completion_criterion',2,'Direct and CPN-controlled replay agree on simulation identities, input identities, executor contract, completed output identities, and injected-failure results; CPN behavior adds only ordering, authorization, dependency, failure, and terminal-state semantics.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.architecture-v2.simulation-execution','completion_criterion',3,'workflows and petrinet.colored import no calculator-specific Quantum ESPRESSO modules; petrinet.colored imports no workflows package; and scientific-domain packages do not import Workflow orchestration.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.architecture-v2.simulation-execution','completion_criterion',4,'Simulation specification and SimulationExecutionResult are explicit separate public boundaries, with mechanical observations distinct from ScientificAnalysis and human-reviewed external research conclusions.');
