INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('human-review-interface.human-decision-recording','authorized_scope',0,'This bounded slice adds the immutable public `HumanReviewDecision` ResultObject and fieldless `HumanReviewDecisionRecorder` ActionObject. Following the human-requested architecture correction, the decision stores the exact immutable packet itself, exact human response, caller-supplied normalized disposition, and contract-compatible explicit scope. Recording reconstructs the canonical `HumanReviewPreparer` result and rejects a packet whose relationships, ordering, or derived status differ. Recording performs no natural-language interpretation, authority inference, persistence, filesystem or Git action, checkpoint mutation, or successor activation.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('human-review-interface.human-decision-recording','completion_criterion',0,'Focused software-verification evidence, public imports, maintained structural evidence validation, Ruff, mypy, deterministic repeated construction, exact response preservation, packet nonmutation, profile/resource identity, documentation links, control-plane parsing, dependency identity, and diff checks are required before handoff.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('human-review-interface.human-decision-recording','exclusion',0,'This task does not authorize JSON serialization, schemas, SQLite, checkpoints, reviewer spawning, successor activation, scientific work, or protected work.');
